namespace App\Traits;

use App\Config\Constants\BillsConstants as BC;
use Illuminate\Database\{Eloquent\Model, Schema\Blueprint};
use Illuminate\Support\Facades\Log;

trait IsNumericBenefit
{
	protected function addNumericBenefitColumns(Blueprint $table, ?float $minBudget = 0.00, ?float $maxBudget = 9999999999.00, ?bool $nullableBudget = true): void
	{
		$table->string('name')->index();
		$table->string('description')->nullable();
		$nullableBudget ? $table->decimal(BC::COL_EXP_BDG, 15, 2)->default($minBudget)->nullable() : $table->decimal(BC::COL_EXP_BDG, 15, 2)->default($minBudget);
		$nullableBudget ? $table->decimal(BC::COL_MAX_BDG, 15, 2)->default($maxBudget)->nullable() : $table->decimal(BC::COL_MAX_BDG, 15, 2)->default($maxBudget);
	}
	protected static function verifyMaxBudget(Model $model): void
	{
		$model->{BC::COL_EXP_BDG} ??= 0.00;
		$model->{BC::COL_MAX_BDG} ??= 9999999999.00;
		if ($model->{BC::COL_EXP_BDG} > $model->{BC::COL_MAX_BDG}) {
			Log::error('Expected budget cannot be greater than maximum budget.', [
				'expected' => $model->{BC::COL_EXP_BDG},
				'maximum' => $model->{BC::COL_MAX_BDG},
				'model_id' => $model->id ?? 'new',
			]);
			$model->{BC::COL_EXP_BDG} = $model->{BC::COL_MAX_BDG};
		}
	}
}

namespace App\Traits;

use App\Config\Constants\DatabaseConstants as DC;
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\{Log, Schema};

trait HasNullableAuditColumns
{
	protected function addAuditColumns(Blueprint $table): void
	{
		$table->timestamps();
		$table->uuid(DC::TABLE_CREATOR)->nullable();
		$table->uuid(DC::TABLE_UPDATER)->nullable();
		foreach ([DC::TABLE_CREATOR, DC::TABLE_UPDATER] as $col)
			$table->foreign($col)
				->references('id')
				->on(DC::TABLE_USERS)
				->nullOnDelete();
	}
	protected function dropAuditColumnForeigns(Blueprint $table, string $tableName): void
	{
		foreach (
			[
				DC::TABLE_UPDATER,
				DC::TABLE_CREATOR,
			] as $column
		) {
			try {
				Schema::hasColumn($tableName, $column)
					&& $table->dropForeign([$column]);
			} catch (\Exception $e) {
				Log::warning(
					'Failed to drop foreign key for '
						. $column
						. ' on table '
						. $tableName
						. ': '
						. $e->getMessage()
				);
			}
		}
	}
}

namespace App\Traits;

use App\Models\User;

trait HasAuditFields
{
	protected static function bootHasAuditFields()
	{
		static::creating(function ($model) {
			if (auth()->check()) {
				$model->created_by = $model->created_by ?? auth()->id();
				$model->updated_by = $model->updated_by ?? auth()->id();
			}
		});

		static::updating(function ($model) {
			if (auth()->check()) {
				$model->updated_by = auth()->id();
			}
		});
	}

	public function creator()
	{
		return $this->belongsTo(User::class, 'created_by');
	}

	public function updater()
	{
		return $this->belongsTo(User::class, 'updated_by');
	}
}

namespace App\Traits;

use App\Config\Constants\{DatabaseConstants as DC, UsersConstants as UC};
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\{Log, Schema};

trait EmployeeConnected
{
	protected function addEmployeeColumns(Blueprint $table, bool $unique = false, bool $nullable = false): void
	{
		$unique ? ($nullable ? $table->uuid(UC::COL_EMP_ID)->unique()->nullable()->index() : $table->uuid(UC::COL_EMP_ID)->index()) : ($nullable ? $table->uuid(UC::COL_EMP_ID)->nullable()->index() : $table->uuid(UC::COL_EMP_ID)->index());
		$nullable ?
			$table->foreign(UC::COL_EMP_ID)
			->references('id')
			->on(DC::TABLE_EMPLOYEES)
			->nullOnDelete() :
			$table->foreign(UC::COL_EMP_ID)
			->references('id')
			->on(DC::TABLE_EMPLOYEES)
			->cascadeOnDelete();
	}
	protected function dropEmployeeForeign(Blueprint $table, string $tableName): void
	{
		try {
			Schema::hasColumn($tableName, UC::COL_EMP_ID) &&
				$table->dropForeign([UC::COL_EMP_ID]);
		} catch (\Exception $e) {
			Log::warning(
				'Failed to drop foreign key for '
					. UC::COL_EMP_ID
					. ' on table '
					. $tableName
					. ': '
					. $e->getMessage()
			);
		}
	}
}

