namespace App\Enums;

enum SalaryType: string
{
	case CLT        = 'clt';
	case PJ         = 'pj';
	case Internship = 'internship';
	case Freelancer = 'freelancer';
	case Other      = 'other';

	public static function normalize(?string $v): ?self
	{
		if ($v === null) return null;
		$v = strtolower(trim($v));
		return match ($v) {
			'clt', 'consolidação das leis do trabalho', 'consolidation of labor laws' => self::CLT,
			'pj', 'pessoa jurídica', 'legal entity'                                   => self::PJ,
			'internship', 'estágio', 'internato'                                      => self::Internship,
			'freelancer', 'freelance', 'autônomo'                                     => self::Freelancer,
			'other', 'outro', 'outros'                                               => self::Other,
			default => self::Other,
		};
	}
}

namespace App\Enums;

use App\Config\Constants\PermissionsConstants as PC;

enum UserType: string
{
	case SuperAdmin = PC::SA;
	case Admin      = PC::ADM;
	case Company    = PC::CPN;
	case Client     = PC::CL;
	case Customer   = PC::CT;
	case Vendor     = PC::VD;
	case Accountant = PC::ACT;

	public static function normalize(string $value): ?self
	{
		$slug = mb_strtolower(trim($value));
		return self::tryFrom($slug);
	}
	public static function isValidValue(string $value): bool
	{
		return self::tryFrom($value) !== null;
	}
	public static function values(): array
	{
		return array_column(self::cases(), 'value');
	}

	public static function names(): array
	{
		return array_column(self::cases(), 'name');
	}
}

